import heapq

def solve(records: list, k: int) -> list:
    # Step 1: aggregate minimum p99 per service in one pass
    service_min = {}
    for service, p99 in records:
        if service not in service_min or p99 < service_min[service]:
            service_min[service] = p99
    # Step 2: find k services with lowest p99 using a max-heap of size k.
    # We store (-p99, svc) so Python's min-heap behaves as a max-heap.
    # The heap top is always the largest p99 among current candidates;
    # when a new service has a lower p99, it evicts the current maximum.
    heap = []
    for svc, p99 in service_min.items():
        heapq.heappush(heap, (-p99, svc))
        if len(heap) > k:
            heapq.heappop(heap)  # drop the highest-p99 service seen so far
    return sorted(svc for _, svc in heap)

