def solve(n: int, dependencies: list) -> int:
    in_degree = [0] * n
    graph = defaultdict(list)
    for a, b in dependencies:
        graph[a].append(b)
        in_degree[b] += 1
    queue = deque(i for i in range(n) if in_degree[i] == 0)
    rounds = 0
    processed = 0
