        rounds += 1
        for _ in range(len(queue)):
            node = queue.popleft()
            processed += 1
            for nb in graph[node]:
                in_degree[nb] -= 1
                if in_degree[nb] == 0:
                    queue.append(nb)
    return rounds if processed == n else -1

