from collections import defaultdict

def solve(services: list[str], edges: list[list[str]]) -> list[list[str]]:
    # Kosaraju's two-pass algorithm for strongly connected components
    graph = defaultdict(list)
    rev = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        rev[v].append(u)  # reverse graph

    # Pass 1: iterative post-order DFS on original graph
    visited = set()
    finish_stack = []  # nodes finish in reverse topological order

    def dfs1(start):
        stack = [(start, iter(graph[start]))]
        while stack:
            node, children = stack[-1]
            try:
                child = next(children)
                if child not in visited:
                    visited.add(child)
                    stack.append((child, iter(graph[child])))
            except StopIteration:
                finish_stack.append(node)  # all neighbours done
                stack.pop()

    for s in services:
        if s not in visited:
            visited.add(s)
            dfs1(s)

    # Pass 2: DFS on reverse graph in reverse finish order
    # Each reachable set in the reverse graph is one SCC
    visited2 = set()
    sccs = []

    def dfs2(start):
        component = []
        stack = [start]
        while stack:
            node = stack.pop()
            component.append(node)
            for nb in rev[node]:
                if nb not in visited2:
                    visited2.add(nb)
                    stack.append(nb)
        return component

    while finish_stack:
        node = finish_stack.pop()
        if node not in visited2:
            visited2.add(node)
            sccs.append(sorted(dfs2(node)))

    return sorted(sccs)

